'use strict';
let directLipSyncBusy=false,characterAudioPreviewTimer=null;
function clearCharacterAudioPreview(){clearInterval(characterAudioPreviewTimer);characterAudioPreviewTimer=null}
async function generateSelectedCharacterMouth(o=object()){if(!isAnimatedCharacter(o)||o.locked)throw Error('Select a character and enable its editing first.');const c=tracks().find(c=>c.id===o.speechTrackId);if(!c)throw Error('Choose this character’s audio first.');if(c.locked)throw Error('Unlock the selected voice clip before generating mouth cues.');if(o.type==='puppet'&&!o.mouth){openImageRig(o,true);return}if(directLipSyncBusy||speechProcessing||recording||audioBusy)throw Error('Wait for the current media task to finish.');stop();clearCharacterAudioPreview();const owner=project,scene=current(),signature=JSON.stringify([c.src,c.offset,c.duration,c.rate]);directLipSyncBusy=true;window.editorTaskBusy=true;updateCharacterVoiceStatus('Generating mouth movement locally…');try{const r=await fetch('/api/lipsync',{method:'POST',headers:{'Content-Type':'audio/wav'},body:sourceAudioSlice(c)}),data=await r.json();if(!r.ok)throw Error(data.error||'Local mouth processing is unavailable.');if(project!==owner||!scene.objects.includes(o)||!tracks().includes(c)||o.locked||c.locked||JSON.stringify([c.src,c.offset,c.duration,c.rate])!==signature)throw Error('The character or voice changed. Generate lip-sync again.');const cues=data.mouthCues;if(!Array.isArray(cues)||!cues.length||cues.some(m=>!Number.isFinite(m.start)||!Number.isFinite(m.end)||m.start<0||m.end<m.start||!/^[A-HX]$/.test(m.value)))throw Error('The speech tool returned invalid mouth timing.');c.mouthCues=cues.map(m=>({start:m.start+c.offset,end:m.end+c.offset,value:m.value}));o.lipSync=true;c.role='narration';save();render();updateCharacterVoiceStatus(c.mouthCues.length+' mouth cues ready. Choose Preview to review.');return cues.length}finally{directLipSyncBusy=false;window.editorTaskBusy=false;if($('generateCharacterLipSync'))$('generateCharacterLipSync').disabled=!!object()?.locked}}
function updateCharacterVoiceStatus(message=null){const o=object(),c=tracks().find(c=>c.id===o?.speechTrackId),status=$('characterVoiceStatus');if(status)status.textContent=message||(c?(c.mouthCues?.length?c.mouthCues.length+' mouth cues ready.':'Audio linked. Generate mouth movement, then preview.'):'1. Choose or import audio. 2. Generate lip-sync. 3. Preview.');if($('previewCharacterVoice'))$('previewCharacterVoice').disabled=!c||directLipSyncBusy;if($('generateCharacterLipSync'))$('generateCharacterLipSync').disabled=!!o?.locked||!c||directLipSyncBusy}
function previewSelectedCharacterVoice(){const o=object(),c=tracks().find(c=>c.id===o?.speechTrackId);if(!o||!c)return toast('Choose character audio first.');if(characterAudioPreviewTimer){clearCharacterAudioPreview();stop();render();return}const start=Math.max(sceneOffset()+clipStart(o),c.start),end=Math.min(sceneOffset()+clipEnd(o),audioEnd(c));if(end<=start)return toast('Move this voice clip so it overlaps the character in this scene.');const actorId=o.id;seekGlobal(start);selectLayers([actorId]);render();play();characterAudioPreviewTimer=setInterval(()=>{if(!playing||globalTime()>=end){clearCharacterAudioPreview();stop();time=clamp(end-sceneOffset(),0,current().duration);render()}},40)}
const controlsBeforeVoiceWorkflow=renderControls;renderControls=function(){controlsBeforeVoiceWorkflow();const o=object();if(!isAnimatedCharacter(o))return;const panel=$('characterVoice')?.closest('details');if(!panel)return;panel.id='characterVoiceWorkflow';panel.open=true;const note=document.createElement('p');note.id='characterVoiceStatus';note.className='note';note.setAttribute('role','status');const preview=storyButton('Preview voice & mouth',previewSelectedCharacterVoice);preview.id='previewCharacterVoice';$('generateCharacterLipSync').after(preview,note);$('generateCharacterLipSync').textContent=tracks().find(c=>c.id===o.speechTrackId)?.mouthCues?.length?'Regenerate lip-sync':'Generate lip-sync';$('generateCharacterLipSync').onclick=()=>generateSelectedCharacterMouth(o).catch(e=>{updateCharacterVoiceStatus(e.message);toast(e.message)});$('characterVoice').addEventListener('change',()=>updateCharacterVoiceStatus());if(!o.lipSync&&o.speechTrackId)updateCharacterVoiceStatus('Audio linked; mouth animation is off. Generate or preview after enabling lip-sync.');else updateCharacterVoiceStatus()};
const stopBeforeCharacterPreview=stop;stop=function(){clearCharacterAudioPreview();stopBeforeCharacterPreview()};
